impl Wire for HostAddress {
    fn encode(&self, writer: &mut Writer) -> Result<()> {
        let mut fixed = vec![0u8; 2usize];
        let mut vars = Writer::new();
        write_i16_at(&mut fixed, 0, self.port)?;
        vars.write_var_string("host", self.host.as_str(), 256usize)?;
        writer.write_slice(&fixed);
        writer.write_slice(vars.as_slice());
        Ok(())
    }

    fn decode(reader: &mut Reader<'_>) -> Result<Self> {
        let fixed = reader.read_slice(2usize)?.to_vec();
        let bits = NullableBitset::default();
        let var_start = reader.position();
        Ok(Self {
            port: read_at(&fixed, 0, |reader| reader.read_i16())?,
            host: { reader.read_var_string("host", 256usize)? },
        })
    }
}

