#[derive(Debug, Clone, PartialEq)]
pub struct MouseMotionEvent {
    /// `mouseButtonType`.
    pub mouse_button_type: Option<Vec<MouseButtonType>>,
    /// `relativeMotion`.
    pub relative_motion: Option<Vector2i>,
}

impl Default for MouseMotionEvent {
    fn default() -> Self {
        Self {
            mouse_button_type: None,
            relative_motion: None,
        }
    }
}

impl Wire for MouseMotionEvent {
    fn encode(&self, writer: &mut Writer) -> Result<()> {
        let mut fixed = vec![0u8; 9usize];
        let mut bits = NullableBitset::new(1usize);
        if self.mouse_button_type.is_some() {
            bits.set(1, true)?;
        }
        if self.relative_motion.is_some() {
            bits.set(0, true)?;
        }
        fixed[..bits.as_bytes().len()].copy_from_slice(bits.as_bytes());
        let mut vars = Writer::new();
        if let Some(value) = &self.relative_motion {
            let mut nested = Writer::new();
            value.encode(&mut nested)?;
            write_slice_at(&mut fixed, 1, nested.as_slice())?;
        }
        if let Some(value) = &self.mouse_button_type {
            vars.write_varint(value.len() as u32)?;
            for element in value.iter() {
                element.write(&mut vars, 1)?;
            }
        } else {
        }
        writer.write_slice(&fixed);
        writer.write_slice(vars.as_slice());
        Ok(())
    }

    fn decode(reader: &mut Reader<'_>) -> Result<Self> {
        let fixed = reader.read_slice(9usize)?.to_vec();
        let bits = NullableBitset::from_bytes(fixed[..1usize].to_vec());
        let var_start = reader.position();
        Ok(Self {
            relative_motion: if bits.is_set(0)? {
                Some(read_at(&fixed, 1, |reader| Vector2i::decode(reader))?)
            } else {
                None
            },
            mouse_button_type: {
                if bits.is_set(1)? {
                    let value = reader.read_array("mouseButtonType", 4096000usize, |reader| {
                        Ok(MouseButtonType::read(reader, 1)?)
                    })?;
                    Some(value)
                } else {
                    None
                }
            },
        })
    }
}

