/// Java `MusicContainer` polymorphic value.
#[derive(Debug, Clone, PartialEq)]
pub enum MusicContainer {
    /// Type id 0.
    SingleTrackMusicContainer(SingleTrackMusicContainer),
    /// Type id 1.
    RandomMusicContainer(RandomMusicContainer),
    /// Type id 2.
    SequenceMusicContainer(SequenceMusicContainer),
    /// Type id 3.
    HorizontalMusicContainer(HorizontalMusicContainer),
    /// Type id 4.
    SegmentMusicContainer(SegmentMusicContainer),
}

impl MusicContainer {
    /// Type id written before the body.
    pub const fn type_id(&self) -> u32 {
        match self {
            Self::SingleTrackMusicContainer(_) => 0,
            Self::RandomMusicContainer(_) => 1,
            Self::SequenceMusicContainer(_) => 2,
            Self::HorizontalMusicContainer(_) => 3,
            Self::SegmentMusicContainer(_) => 4,
        }
    }

    /// Encode the type id and body.
    pub fn encode(&self, writer: &mut Writer) -> Result<()> {
        writer.write_varint(self.type_id())?;
        match self {
            Self::SingleTrackMusicContainer(value) => value.encode(writer),
            Self::RandomMusicContainer(value) => value.encode(writer),
            Self::SequenceMusicContainer(value) => value.encode(writer),
            Self::HorizontalMusicContainer(value) => value.encode(writer),
            Self::SegmentMusicContainer(value) => value.encode(writer),
        }
    }

    /// Decode a type id and body.
    pub fn decode(reader: &mut Reader<'_>) -> Result<Self> {
        match reader.read_varint()? {
            0 => Ok(Self::SingleTrackMusicContainer(
                SingleTrackMusicContainer::decode(reader)?,
            )),
            1 => Ok(Self::RandomMusicContainer(RandomMusicContainer::decode(
                reader,
            )?)),
            2 => Ok(Self::SequenceMusicContainer(
                SequenceMusicContainer::decode(reader)?,
            )),
            3 => Ok(Self::HorizontalMusicContainer(
                HorizontalMusicContainer::decode(reader)?,
            )),
            4 => Ok(Self::SegmentMusicContainer(SegmentMusicContainer::decode(
                reader,
            )?)),
            other => Err(crate::io::ProtocolError::InvalidEnum {
                type_name: "MusicContainer",
                value: i64::from(other),
            }),
        }
    }

    /// Encoded size.
    pub fn compute_size(&self) -> Result<usize> {
        let mut writer = Writer::new();
        self.encode(&mut writer)?;
        Ok(writer.len())
    }
}

impl Default for MusicContainer {
    fn default() -> Self {
        Self::SingleTrackMusicContainer(Default::default())
    }
}

