/// Java `ParamValue` polymorphic value.
#[derive(Debug, Clone, PartialEq)]
pub enum ParamValue {
    /// Type id 0.
    StringParamValue(StringParamValue),
    /// Type id 1.
    BoolParamValue(BoolParamValue),
    /// Type id 2.
    DoubleParamValue(DoubleParamValue),
    /// Type id 3.
    IntParamValue(IntParamValue),
    /// Type id 4.
    LongParamValue(LongParamValue),
}

impl ParamValue {
    /// Type id written before the body.
    pub const fn type_id(&self) -> u32 {
        match self {
            Self::StringParamValue(_) => 0,
            Self::BoolParamValue(_) => 1,
            Self::DoubleParamValue(_) => 2,
            Self::IntParamValue(_) => 3,
            Self::LongParamValue(_) => 4,
        }
    }

    /// Encode the type id and body.
    pub fn encode(&self, writer: &mut Writer) -> Result<()> {
        writer.write_varint(self.type_id())?;
        match self {
            Self::StringParamValue(value) => value.encode(writer),
            Self::BoolParamValue(value) => value.encode(writer),
            Self::DoubleParamValue(value) => value.encode(writer),
            Self::IntParamValue(value) => value.encode(writer),
            Self::LongParamValue(value) => value.encode(writer),
        }
    }

    /// Decode a type id and body.
    pub fn decode(reader: &mut Reader<'_>) -> Result<Self> {
        match reader.read_varint()? {
            0 => Ok(Self::StringParamValue(StringParamValue::decode(reader)?)),
            1 => Ok(Self::BoolParamValue(BoolParamValue::decode(reader)?)),
            2 => Ok(Self::DoubleParamValue(DoubleParamValue::decode(reader)?)),
            3 => Ok(Self::IntParamValue(IntParamValue::decode(reader)?)),
            4 => Ok(Self::LongParamValue(LongParamValue::decode(reader)?)),
            other => Err(crate::io::ProtocolError::InvalidEnum {
                type_name: "ParamValue",
                value: i64::from(other),
            }),
        }
    }

    /// Encoded size.
    pub fn compute_size(&self) -> Result<usize> {
        let mut writer = Writer::new();
        self.encode(&mut writer)?;
        Ok(writer.len())
    }
}

impl Default for ParamValue {
    fn default() -> Self {
        Self::StringParamValue(Default::default())
    }
}

