/// Java `Selector` polymorphic value.
#[derive(Debug, Clone, PartialEq)]
pub enum Selector {
    /// Type id 0.
    AOECircleSelector(AOECircleSelector),
    /// Type id 1.
    AOECylinderSelector(AOECylinderSelector),
    /// Type id 2.
    RaycastSelector(RaycastSelector),
    /// Type id 3.
    HorizontalSelector(HorizontalSelector),
    /// Type id 4.
    StabSelector(StabSelector),
    /// Type id 5.
    DonutSelector(DonutSelector),
}

impl Selector {
    /// Type id written before the body.
    pub const fn type_id(&self) -> u32 {
        match self {
            Self::AOECircleSelector(_) => 0,
            Self::AOECylinderSelector(_) => 1,
            Self::RaycastSelector(_) => 2,
            Self::HorizontalSelector(_) => 3,
            Self::StabSelector(_) => 4,
            Self::DonutSelector(_) => 5,
        }
    }

    /// Encode the type id and body.
    pub fn encode(&self, writer: &mut Writer) -> Result<()> {
        writer.write_varint(self.type_id())?;
        match self {
            Self::AOECircleSelector(value) => value.encode(writer),
            Self::AOECylinderSelector(value) => value.encode(writer),
            Self::RaycastSelector(value) => value.encode(writer),
            Self::HorizontalSelector(value) => value.encode(writer),
            Self::StabSelector(value) => value.encode(writer),
            Self::DonutSelector(value) => value.encode(writer),
        }
    }

    /// Decode a type id and body.
    pub fn decode(reader: &mut Reader<'_>) -> Result<Self> {
        match reader.read_varint()? {
            0 => Ok(Self::AOECircleSelector(AOECircleSelector::decode(reader)?)),
            1 => Ok(Self::AOECylinderSelector(AOECylinderSelector::decode(
                reader,
            )?)),
            2 => Ok(Self::RaycastSelector(RaycastSelector::decode(reader)?)),
            3 => Ok(Self::HorizontalSelector(HorizontalSelector::decode(
                reader,
            )?)),
            4 => Ok(Self::StabSelector(StabSelector::decode(reader)?)),
            5 => Ok(Self::DonutSelector(DonutSelector::decode(reader)?)),
            other => Err(crate::io::ProtocolError::InvalidEnum {
                type_name: "Selector",
                value: i64::from(other),
            }),
        }
    }

    /// Encoded size.
    pub fn compute_size(&self) -> Result<usize> {
        let mut writer = Writer::new();
        self.encode(&mut writer)?;
        Ok(writer.len())
    }
}

impl Default for Selector {
    fn default() -> Self {
        Self::AOECircleSelector(Default::default())
    }
}

