/// Java `WorldEnvironment`.
#[derive(Debug, Clone, PartialEq)]
pub struct WorldEnvironment {
    /// `id`.
    pub id: Option<String>,
    /// `waterTint`.
    pub water_tint: Option<Color>,
    /// `fluidParticles`.
    pub fluid_particles: Option<BTreeMap<i32, FluidParticle>>,
    /// `tagIndexes`.
    pub tag_indexes: Option<Vec<i32>>,
}

impl Default for WorldEnvironment {
    fn default() -> Self {
        Self {
            id: None,
            water_tint: None,
            fluid_particles: None,
            tag_indexes: None,
        }
    }
}

impl Wire for WorldEnvironment {
    fn encode(&self, writer: &mut Writer) -> Result<()> {
        let mut fixed = vec![0u8; 16usize];
        let mut bits = NullableBitset::new(1usize);
        if self.id.is_some() {
            bits.set(1, true)?;
        }
        if self.water_tint.is_some() {
            bits.set(0, true)?;
        }
        if self.fluid_particles.is_some() {
            bits.set(2, true)?;
        }
        if self.tag_indexes.is_some() {
            bits.set(3, true)?;
        }
        fixed[..bits.as_bytes().len()].copy_from_slice(bits.as_bytes());
        let mut vars = Writer::new();
        if let Some(value) = &self.water_tint {
            let mut nested = Writer::new();
            value.encode(&mut nested)?;
            write_slice_at(&mut fixed, 1, nested.as_slice())?;
        }
        if let Some(value) = &self.id {
            write_i32_at(&mut fixed, 4, vars.len() as i32)?;
            vars.write_var_string("id", value.as_str(), 4096000usize)?;
        } else {
            write_i32_at(&mut fixed, 4, -1)?;
        }
        if let Some(value) = &self.fluid_particles {
            write_i32_at(&mut fixed, 8, vars.len() as i32)?;
            vars.write_varint(value.len() as u32)?;
            for (key, map_value) in value.iter() {
                vars.write_i32(*key);
                map_value.encode(&mut vars)?;
            }
        } else {
            write_i32_at(&mut fixed, 8, -1)?;
        }
        if let Some(value) = &self.tag_indexes {
            write_i32_at(&mut fixed, 12, vars.len() as i32)?;
            vars.write_varint(value.len() as u32)?;
            for element in value.iter() {
                vars.write_i32(*element);
            }
        } else {
            write_i32_at(&mut fixed, 12, -1)?;
        }
        writer.write_slice(&fixed);
        writer.write_slice(vars.as_slice());
        Ok(())
    }

    fn decode(reader: &mut Reader<'_>) -> Result<Self> {
        let fixed = reader.read_slice(16usize)?.to_vec();
        let bits = NullableBitset::from_bytes(fixed[..1usize].to_vec());
        let var_start = reader.position();
        Ok(Self {
            water_tint: if bits.is_set(0)? {
                Some(read_at(&fixed, 1, |reader| Color::decode(reader))?)
            } else {
                None
            },
            id: {
                if bits.is_set(1)? {
                    let expected = (reader.position() - var_start) as i32;
                    let found = read_at(&fixed, 4, |reader| reader.read_i32())?;
                    if found != expected {
                        return Err(crate::io::ProtocolError::NonCanonicalOffset {
                            field: "id",
                            found,
                            expected,
                        });
                    }
                    let value = reader.read_var_string("id", 4096000usize)?;
                    Some(value)
                } else {
                    let found = read_at(&fixed, 4, |reader| reader.read_i32())?;
                    if found != -1 {
                        return Err(crate::io::ProtocolError::NonCanonicalOffset {
                            field: "id",
                            found,
                            expected: -1,
                        });
                    }
                    None
                }
            },
            fluid_particles: {
                if bits.is_set(2)? {
                    let expected = (reader.position() - var_start) as i32;
                    let found = read_at(&fixed, 8, |reader| reader.read_i32())?;
                    if found != expected {
                        return Err(crate::io::ProtocolError::NonCanonicalOffset {
                            field: "fluidParticles",
                            found,
                            expected,
                        });
                    }
                    let value = {
                        let count = reader.read_length("fluidParticles", 4096000usize)?;
                        let mut mapped = BTreeMap::new();
                        for _ in 0..count {
                            let key = reader.read_i32()?;
                            let map_value = FluidParticle::decode(reader)?;
                            if mapped.insert(key.clone(), map_value).is_some() {
                                return Err(crate::io::ProtocolError::DuplicateMapKey {
                                    field: "fluidParticles",
                                    key: format!("{:?}", key),
                                });
                            }
                        }
                        mapped
                    };
                    Some(value)
                } else {
                    let found = read_at(&fixed, 8, |reader| reader.read_i32())?;
                    if found != -1 {
                        return Err(crate::io::ProtocolError::NonCanonicalOffset {
                            field: "fluidParticles",
                            found,
                            expected: -1,
                        });
                    }
                    None
                }
            },
            tag_indexes: {
                if bits.is_set(3)? {
                    let expected = (reader.position() - var_start) as i32;
                    let found = read_at(&fixed, 12, |reader| reader.read_i32())?;
                    if found != expected {
                        return Err(crate::io::ProtocolError::NonCanonicalOffset {
                            field: "tagIndexes",
                            found,
                            expected,
                        });
                    }
                    let value = reader
                        .read_array("tagIndexes", 4096000usize, |reader| Ok(reader.read_i32()?))?;
                    Some(value)
                } else {
                    let found = read_at(&fixed, 12, |reader| reader.read_i32())?;
                    if found != -1 {
                        return Err(crate::io::ProtocolError::NonCanonicalOffset {
                            field: "tagIndexes",
                            found,
                            expected: -1,
                        });
                    }
                    None
                }
            },
        })
    }
}

